index 3a1f2c4..9b7d105 100644
--- a/hooks/useForm.ts
+++ b/hooks/useForm.ts
@@ -12,9 +12,20 @@ export const useForm = (initial: FormValue) => {
   const [value, setValue] = useState(initial)
   const [error, setError] = useState<string | null>(null)

+  const validate = (v: FormValue): ValidationResult => {
+    if (v.title.trim() === '') {
+      return { ok: false, message: '必須です' }
+    }
+    return { ok: true }
+  }
+
   const save = async () => {
-    setError(null)
-    await api.save(value)
+    const result = validate(value)
+    if (!result.ok) {
+      setError(result.message)
+      return
+    }
+    await api.save(value)
   }

   return { value, setValue, error, save }
